// CountryByISO2 returns the geometry for a country by its ISO2 code.
func CountryByISO2(iso2 string) (CountryGeometry, bool) {
	for _, c := range AllCountries {
		if c.ISO2 == iso2 {
			return c, true
		}
	}
	return CountryGeometry{}, false
}
